<?php
include_once PAD.'subs/printables/_lib/registers.php';
function padPrintableTimesheetPages($items,$paper,$mode='decimal',$blank=0){
 if(count($items)>2000||!in_array($mode,['decimal','clock'],TRUE)||!is_int($blank)||$blank<0||$blank>100)throw new InvalidArgumentException('timesheet expects decimal/clock mode, max 2000 rows and 100 blanks');$widths=[.24,.29,.23,.24];$pages=[];$page=[];$used=0;
 foreach(array_merge($items,array_fill(0,$blank,'')) as $item){$text=padRegisterPlain($item);$values=$text===''?['','','','']:array_map('trim',explode('|',$text));if(count($values)!==4)throw new InvalidArgumentException('timesheet row: person | project | YYYY-MM-DD | duration');if($values[2]!==''){$d=DateTimeImmutable::createFromFormat('!Y-m-d',$values[2]);if(!$d||$d->format('Y-m-d')!==$values[2])throw new InvalidArgumentException('timesheet invalid date');}if($values[3]!==''&&!preg_match($mode==='decimal'?'/^\d{1,6}(?:\.\d{1,4})?$/D':'/^\d{1,6}:[0-5]\d$/D',$values[3]))throw new InvalidArgumentException('timesheet duration does not match mode');$lines=[];$height=10;foreach($values as $i=>$value){if(mb_strlen($value)>500)throw new InvalidArgumentException('timesheet field too long');$lines[]=padRegisterWrap($value,max(8,(int)(($paper[0]-20)*$widths[$i]/2.15)-2));$height=max($height,count($lines[$i])*4.5+4);}if($height>$paper[1]-65)throw new InvalidArgumentException('timesheet row too tall');if($used+$height>$paper[1]-65&&$page){$pages[]=$page;$page=[];$used=0;}$page[]=['lines'=>$lines,'height'=>$height];$used+=$height;}
 if($page||!$pages)$pages[]=$page;return $pages;
}
function padPrintableTimesheetPlan(){
 [$name,$paper]=padPrintablePaper(['a4'=>PAD_PRINTABLE_PAPERS['a4'],'letter'=>PAD_PRINTABLE_PAPERS['letter']],'a4');$title=padPrintableText('title','Timesheet');$mode=padPrintableText('mode','decimal');$total=padPrintableText('total','');$blank=padTagParm('blankrows',0);if(filter_var($blank,FILTER_VALIDATE_INT)===FALSE)throw new InvalidArgumentException('blankrows must be integer');$count=0;
 return padPrintablePlan(['name'=>['page','pages'],'paper'=>$paper,'paperName'=>$name,'font'=>'sans','documentCopies'=>TRUE,
 'prepare'=>function($items)use($paper,$mode,$blank,&$count){$pages=padPrintableTimesheetPages($items,$paper,$mode,(int)$blank);$count=count($pages);return array_map(fn($rows)=>json_encode($rows,JSON_THROW_ON_ERROR),$pages);},
 'item'=>function($cell,$parts,$n)use($paper,$title,$mode,$total,&$count){if(!$parts)return [];$rows=json_decode($parts[''],TRUE);$draw=[['box',10,10,$paper[0]-20,10,padWidgetAttr($title),['size'=>14,'pad'=>0]],['box',10,20,$paper[0]-20,7,padWidgetAttr($mode==='decimal'?'Decimal hours':'Clock duration (hours:minutes)'),['size'=>8,'pad'=>0]],['box',10,$paper[1]-15,$paper[0]-20,6,padWidgetAttr('Page '.($n%max(1,$count)+1).' of '.$count.($total!==''?' — Supplied total: '.$total:'')),['size'=>8,'pad'=>0]]];$widths=[.24,.29,.23,.24];$x=10;$y=29;foreach(['Person','Project','Date','Duration'] as $i=>$label){$w=($paper[0]-20)*$widths[$i];$draw[]=['box',$x,$y,$w,8,$label,['size'=>8,'pad'=>1]];$x+=$w;}$y+=8;
 foreach($rows as $row){$x=10;foreach($widths as $i=>$ratio){$w=($paper[0]-20)*$ratio;$draw[]=['rect',$x,$y,$w,$row['height'],['stroke'=>'#aaaaaa','width'=>.2]];foreach($row['lines'][$i] as $j=>$line)$draw[]=['box',$x+2,$y+2+$j*4.5,$w-4,4.5,padWidgetAttr($line),['size'=>8,'pad'=>0]];$x+=$w;}$y+=$row['height'];}return $draw;}]);
}
